css:
.ratcheck-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e2ec;
    background: radial-gradient(140% 120% at 0% 0%, #11202e 0%, #0a141d 55%, #060c12 100%);
    border-radius: 18px;
    border: 1px solid #1d3340;
}

.ratcheck-container * {
    box-sizing: border-box;
}

.ratcheck-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0d2433 0%, #123247 55%, #0a3b3f 100%);
    color: #eaf4f7;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #1f4254;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}

.ratcheck-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f4fbfd;
}

.ratcheck-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #7fd0c4;
    background: rgba(127, 208, 196, 0.10);
    border: 1px solid rgba(127, 208, 196, 0.28);
    padding: 5px 14px;
    border-radius: 999px;
}

.ratcheck-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #b6c8d6;
}

.ratcheck-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6c7;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.ratcheck-period-counter #currentDay,
.ratcheck-period-counter #maxPeriods {
    font-weight: 800;
    color: #f4fbfd;
}

.ratcheck-round-name {
    background: #15384a;
    color: #8fe3d4;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #1f4f63;
}

.ratcheck-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffb486;
    background: rgba(255, 120, 60, 0.12);
    border: 1px solid rgba(255, 120, 60, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.ratcheck-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.ratcheck-status-card {
    background: #0f1f2b;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1c3543;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
    border-top: 4px solid #2aa6c9;
}

.ratcheck-card-rationality { border-top-color: #2aa6c9; }
.ratcheck-card-quality { border-top-color: #38c587; }
.ratcheck-card-credibility { border-top-color: #c9a93f; }
.ratcheck-card-clock { border-top-color: #d8723f; }

.ratcheck-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #7f99aa;
}

.ratcheck-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f4fbfd;
    font-variant-numeric: tabular-nums;
}

.ratcheck-card-rationality .ratcheck-value { color: #56c6e6; }
.ratcheck-card-quality .ratcheck-value { color: #4fe0a0; }
.ratcheck-card-credibility .ratcheck-value { color: #e6c75c; }
.ratcheck-card-clock .ratcheck-value { color: #f08e54; }

.ratcheck-sublabel {
    font-size: 0.75rem;
    color: #7f99aa;
    line-height: 1.35;
}

.ratcheck-card-quality.ratcheck-q-good .ratcheck-value { color: #4fe0a0; }
.ratcheck-card-quality.ratcheck-q-bad .ratcheck-value { color: #ef6a5a; }
.ratcheck-card-credibility.ratcheck-cred-low .ratcheck-value { color: #ef6a5a; }
.ratcheck-card-clock.ratcheck-clock-out .ratcheck-value { color: #ef6a5a; }

.ratcheck-budget-bar,
.ratcheck-npv-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 14px;
    font-weight: 700;
    font-size: 0.92rem;
}

.ratcheck-budget-bar {
    background: #0d1c27;
    border: 1px solid #1c3543;
    color: #b6c8d6;
}

.ratcheck-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #56c6e6;
    font-variant-numeric: tabular-nums;
}

.ratcheck-npv-bar {
    background: linear-gradient(90deg, #0e2a23 0%, #0d1c27 100%);
    border: 1px solid #1f4f3f;
    color: #9fc9b8;
    margin-bottom: 18px;
}

.ratcheck-npv-bar #npvDisplay {
    font-size: 1.15rem;
    letter-spacing: 0.3px;
    font-variant-numeric: tabular-nums;
    color: #4fe0a0;
}

.ratcheck-npv-bar.ratcheck-npv-negative #npvDisplay {
    color: #ef6a5a;
}

.ratcheck-briefing {
    display: flex;
    gap: 14px;
    background: #0f1f2b;
    border-left: 5px solid #2aa6c9;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #1c3543;
    border-left-width: 5px;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
}

.ratcheck-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.ratcheck-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f4fbfd;
    margin-bottom: 6px;
}

.ratcheck-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #b6c8d6;
}

.ratcheck-briefing-text strong { color: #4fe0a0; }
.ratcheck-briefing-text em { color: #ffb486; font-style: italic; }

.ratcheck-controls {
    background: #0f1f2b;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1c3543;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
}

.ratcheck-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f4fbfd;
    border-bottom: 2px solid #1c3543;
    padding-bottom: 8px;
}

.ratcheck-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cfe0ec;
    margin: 14px 0 6px;
}

.ratcheck-container select,
.ratcheck-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #28475a;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a151e;
    color: #eaf4f7;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.ratcheck-container select:focus,
.ratcheck-container input[type="number"]:focus {
    outline: none;
    border-color: #2aa6c9;
    box-shadow: 0 0 0 3px rgba(42, 166, 201, 0.22);
}

.ratcheck-container select option {
    background-color: #0a151e;
    color: #eaf4f7;
}

.ratcheck-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2aa6c9;
}

.ratcheck-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #7fd0c4;
    margin-top: 4px;
}

.ratcheck-range-readout span:last-child {
    color: #4fe0a0;
    font-weight: 800;
}

.ratcheck-hint {
    font-size: 0.8rem;
    color: #7f99aa;
    margin-top: 4px;
    line-height: 1.4;
}

.ratcheck-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.ratcheck-container .btn-primary {
    background: linear-gradient(135deg, #1c7fa6 0%, #2aa6c9 100%);
    border: none;
    color: #04141c;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(42, 166, 201, 0.30);
}

.ratcheck-container .btn-primary:hover {
    filter: brightness(1.08);
}

.ratcheck-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #28475a;
    color: #9fb6c7;
    background: transparent;
}

.ratcheck-container .btn-outline-secondary:hover {
    background: #15293580;
    color: #cfe0ec;
}

.ratcheck-coach {
    background: linear-gradient(135deg, #11202e 0%, #0d2433 100%);
    color: #d7e2ec;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #234455;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.ratcheck-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7fd0c4;
    margin-bottom: 8px;
}

.ratcheck-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c4d6e2;
}

.ratcheck-coach-body strong { color: #6fe0b3; }
.ratcheck-coach-body em { color: #ffc1a0; font-style: italic; }

.ratcheck-history,
.ratcheck-chart {
    background: #0f1f2b;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1c3543;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
}

.ratcheck-history h3,
.ratcheck-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f4fbfd;
}

.ratcheck-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d6e2;
}

.ratcheck-container table#usfHistoryTable th {
    background: #13283400;
    color: #7fd0c4;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1f4254;
}

.ratcheck-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #162a36;
    color: #c4d6e2;
}

.ratcheck-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0c1822;
}

.ratcheck-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .ratcheck-container {
        padding: 14px;
    }
    .ratcheck-header h1 {
        font-size: 1.7rem;
    }
    .ratcheck-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .ratcheck-value {
        font-size: 2rem;
    }
    .ratcheck-clock {
        margin-left: 0;
    }
    .ratcheck-period-counter {
        font-size: 0.88rem;
    }
    .ratcheck-budget-bar,
    .ratcheck-npv-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .ratcheck-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (ratcheck) ---- */
.ratcheck-completion { padding: 8px 4px 4px; }
.ratcheck-cm-head { text-align: center; margin-bottom: 16px; }
.ratcheck-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #3f8fb0; }
.ratcheck-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6faec4; }
.ratcheck-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #223540; }
.ratcheck-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.ratcheck-cm-yes { background: rgba(63,143,176,0.16); color: #2c6f8a; border: 1px solid rgba(63,143,176,0.55); }
.ratcheck-cm-no { background: rgba(190,70,55,0.12); color: #a5412c; border: 1px solid rgba(190,70,55,0.45); }
.ratcheck-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.ratcheck-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(63,143,176,0.08); border: 1px solid rgba(63,143,176,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.ratcheck-cm-mv { display: block; font-size: 1.3rem; font-weight: 800; color: #2f7793; }
.ratcheck-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #66717a; text-transform: uppercase; letter-spacing: 0.03em; }
.ratcheck-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #223540; }
.ratcheck-cm-insights { margin: 0; padding-left: 20px; }
.ratcheck-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #33424c; }

