(function() {
    'use strict';

    class RationalityAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Rationality Check`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (EUR).
            this.CLAIMED_NPV = 5.2;        // +EUR 5.2M on the COO's 6% growth
            this.CORRECTED_NPV = -3.8;     // -EUR 3.8M at realistic 1.5% growth
            this.VENDOR_SAVINGS = 7.6;     // EUR 7.6M/yr from the vendor's deck
            this.INDEP_SAVINGS = 4.9;      // EUR 4.9M/yr independent estimate (-36%)
            this.SUNK = 1.4;               // EUR 1.4M feasibility + pilot (irrelevant)
            this.INVESTMENT = 24;          // EUR 24M total
            this.PILOT = 9;                // EUR 9M phased Plant 2 pilot
            this.INDEP_COST = 40;          // EUR 40K independent study
            this.BUDGET_CAP = 120;         // EUR 120K verification budget cap (in EUR k)
            this.CLOCK_START = 9.0;        // 9 working days

            // Concept-correct play (the textbook controlling sequence).
            this.TRUE_TOPBIAS = `optimism`;   // the 6% growth flips the case
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rationality: 20,
                    quality: 15,
                    credibility: 40,
                    days: this.CLOCK_START,
                    budgetUsed: 0,
                    workingNpv: this.CLAIMED_NPV,
                    capitulated: false,
                    detonated: false,
                    signedOriginal: false,
                    rationalityHistory: [20],
                    qualityHistory: [15],
                    credibilityHistory: [40],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed MIDDLING / NEUTRAL — a click-through must not auto-win.
                state.decisions = {
                    approach: `recompute`,
                    topbias: `anchoring`,
                    rigor: 50,
                    growth: `flat3`,
                    sunk: `partial`,
                    savings: `discount`,
                    ramp: 3,
                    stance: `redesign`,
                    evidence: `evidence`,
                    plea: `accommodate`,
                    tone: 50,
                    signoff: `corrected`,
                    phased: `allornothing`,
                    governance: `review`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const v = (id) => { const el = document.getElementById(id); return el ? el.value : null; };

            if (round === 1) {
                const a = v(`approachInput`); if (a !== null) decisions.approach = a;
                const tb = v(`topbiasInput`); if (tb !== null) decisions.topbias = tb;
                const r = document.getElementById(`rigorInput`);
                if (r) decisions.rigor = parseInt(r.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const g = v(`growthInput`); if (g !== null) decisions.growth = g;
                const s = v(`sunkInput`); if (s !== null) decisions.sunk = s;
                const sv = v(`savingsInput`); if (sv !== null) decisions.savings = sv;
                const rp = document.getElementById(`rampInput`);
                if (rp) decisions.ramp = parseInt(rp.value, 10);
                if (!Number.isFinite(decisions.ramp) || decisions.ramp < 0 || decisions.ramp > 14) {
                    warn(`warn_ramp_range`); return false;
                }
            } else if (round === 3) {
                const st = v(`stanceInput`); if (st !== null) decisions.stance = st;
                const ev = v(`evidenceInput`); if (ev !== null) decisions.evidence = ev;
                const pl = v(`pleaInput`); if (pl !== null) decisions.plea = pl;
                const tn = document.getElementById(`toneInput`);
                if (tn) decisions.tone = parseInt(tn.value, 10);
                if (!Number.isFinite(decisions.tone) || decisions.tone < 0 || decisions.tone > 100) {
                    warn(`warn_tone_range`); return false;
                }
            } else if (round === 4) {
                const sg = v(`signoffInput`); if (sg !== null) decisions.signoff = sg;
                const ph = v(`phasedInput`); if (ph !== null) decisions.phased = ph;
                const gv = v(`governanceInput`); if (gv !== null) decisions.governance = gv;
                const cv = document.getElementById(`convictionInput`);
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Three KPIs move on deltas. Start low, keep headroom.
            let ratDelta = 0, qualDelta = 0, credDelta = 0;
            let daysSpent = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Round 1 — detect BEFORE compute (Common Error 1).
                // Deltas are sized so the perfect path lands near (not far past) 100 — no
                // saturation slack that would let a flagged Common Error coast into the top tier.
                if (d.approach === `biasfirst`) {
                    ratDelta += 11; credDelta += 5; coachKey = `coach_r1_biasfirst`;
                } else if (d.approach === `recompute`) {
                    // Computing before critiquing (Common Error 1) is a real loss, not a small gain.
                    ratDelta -= 4; qualDelta += 1; coachKey = `coach_r1_recompute`;
                } else { // accept
                    ratDelta -= 12; credDelta -= 4; coachKey = `coach_r1_accept`;
                }

                // The single bias that flips the case is OPTIMISM (6% growth -> -EUR 3.8M).
                if (d.topbias === this.TRUE_TOPBIAS) {
                    ratDelta += 8; qualDelta += 4;
                    if (d.approach === `biasfirst`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.topbias === `anchoring`) {
                    // Real bias, but not the case-flipping one.
                    ratDelta += 1; qualDelta += 1; coachKey = `coach_r1_anchoring`;
                } else if (d.topbias === `sunk`) {
                    ratDelta -= 2; coachKey = `coach_r1_sunk`;
                } else { // none
                    ratDelta -= 10; qualDelta -= 4; credDelta -= 3; coachKey = `coach_r1_none`;
                }

                // Evidential rigor: tie each bias to a line in the model.
                if (d.rigor >= 70) { ratDelta += 5; credDelta += 3; }
                else if (d.rigor >= 40) { ratDelta += 1; }
                else { ratDelta -= 6; credDelta -= 2; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.approach === `biasfirst` && d.topbias === this.TRUE_TOPBIAS) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Round 2 — demand the right analysis.
                // Growth anchor: scenario range beats a single compromise, beats keeping 6%.
                switch (d.growth) {
                    case `scenario`: ratDelta += 7; qualDelta += 8; coachKey = `coach_r2_scenario`; break;
                    case `flat3`: ratDelta -= 1; qualDelta += 1; coachKey = `coach_r2_flat3`; break;
                    case `keep6`: ratDelta -= 9; qualDelta -= 10; credDelta -= 3; coachKey = `coach_r2_keep6`; break;
                }

                // Sunk cost: strip it ENTIRELY (Common Error 3). Partial < strip; keep is wrong.
                switch (d.sunk) {
                    case `strip`: ratDelta += 6; qualDelta += 5; coachKey = (d.growth === `scenario`) ? coachKey : `coach_r2_strip`; break;
                    case `partial`: ratDelta -= 3; qualDelta -= 3; coachKey = `coach_r2_partial`; break;
                    case `keep`: ratDelta -= 10; qualDelta -= 8; coachKey = `coach_r2_keepsunk`; break;
                }

                // Vendor savings: commission the independent estimate (Common Error 2 / anchoring).
                switch (d.savings) {
                    case `independent`: ratDelta += 6; qualDelta += 6; credDelta += 5; spend += this.INDEP_COST; daysSpent += 3; coachKey = `coach_r2_independent`; break;
                    case `discount`: ratDelta += 1; qualDelta += 1; coachKey = `coach_r2_discount`; break;
                    case `accept`: ratDelta -= 11; qualDelta -= 10; credDelta -= 5; coachKey = `coach_r2_acceptsav`; break;
                }

                // Ramp: comparable installs needed 9-14 months; month-1 imports optimism.
                if (d.ramp >= 9 && d.ramp <= 14) { ratDelta += 4; qualDelta += 4; }
                else if (d.ramp >= 5) { ratDelta += 1; qualDelta += 1; }
                else if (d.ramp >= 1) { ratDelta -= 3; qualDelta -= 2; coachKey = `coach_r2_shortramp`; }
                else { ratDelta -= 6; qualDelta -= 5; coachKey = `coach_r2_noramp`; }

                summaryKey = (d.growth === `scenario` && d.sunk === `strip` && d.savings === `independent`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Round 3 — confront the sponsor with evidence, not authority (Common Error 4).
                // Stance: conditional phased pilot is the bravest-smartest; capitulate is worst.
                switch (d.stance) {
                    case `conditional`: qualDelta += 10; credDelta += 6; ratDelta += 3; coachKey = `coach_r3_conditional`; break;
                    case `clearno`: qualDelta += 4; credDelta += 1; coachKey = `coach_r3_clearno`; break;
                    case `redesign`: qualDelta += 3; credDelta += 1; coachKey = `coach_r3_redesign`; break;
                    case `capitulate`: qualDelta -= 14; credDelta -= 12; ratDelta -= 9; ds.capitulated = true; coachKey = `coach_r3_capitulate`; break;
                }

                // Lead with evidence, never authority or deference.
                switch (d.evidence) {
                    case `evidence`: credDelta += 8; ratDelta += 4; break;
                    case `authority`: credDelta -= 7; coachKey = `coach_r3_authority`; break;
                    case `defer`: credDelta -= 5; qualDelta -= 5; coachKey = `coach_r3_defer`; break;
                }

                // The sunk-cost plea: reject it cleanly.
                switch (d.plea) {
                    case `reject`: ratDelta += 7; qualDelta += 3; break;
                    case `accommodate`: ratDelta -= 2; coachKey = `coach_r3_accommodate`; break;
                    case `concede`: ratDelta -= 8; qualDelta -= 5; coachKey = `coach_r3_concede`; break;
                }

                // Relationship tone: a middle band protects the relationship without folding.
                // Too low detonates it; too high becomes capitulation.
                if (d.tone <= 20) { credDelta -= 9; ds.detonated = true; coachKey = `coach_r3_detonate`; }
                else if (d.tone >= 85) { credDelta -= 5; qualDelta -= 5; coachKey = `coach_r3_toosoft`; }
                else if (d.tone >= 45 && d.tone <= 75) { credDelta += 6; }
                else { credDelta += 2; }

                summaryKey = (d.stance === `conditional` && d.evidence === `evidence` && d.plea === `reject`) ? `sum_r3_good` : (d.stance === `capitulate` ? `sum_r3_capitulate` : `sum_r3_weak`);
            } else if (round === 4) {
                // Round 4 — escalate or endorse; design the safeguards.
                // Sign-off: corrected/phased is the defensible call; original is a covenant bet.
                switch (d.signoff) {
                    case `corrected`: qualDelta += 12; ratDelta += 6; credDelta += 5; coachKey = `coach_r4_corrected`; break;
                    case `escalate`: {
                        // Escalation only works with airtight evidence (Common Error 5).
                        const armed = state.decisions.savings === `independent` || ds.workingNpv < 0;
                        if (armed && ds.rationality >= 55) { qualDelta += 8; credDelta += 3; coachKey = `coach_r4_escalate_armed`; }
                        else { qualDelta -= 9; credDelta -= 11; coachKey = `coach_r4_escalate_weak`; }
                        break;
                    }
                    case `original`: qualDelta -= 16; ratDelta -= 7; credDelta -= 13; ds.signedOriginal = true; coachKey = `coach_r4_original`; break;
                }

                // Phased commitment converts an irreversible bet into a real option.
                switch (d.phased) {
                    case `milestones`: qualDelta += 9; ratDelta += 3; coachKey = (d.signoff === `corrected`) ? coachKey : `coach_r4_milestones`; break;
                    case `allornothing`: qualDelta -= 7; coachKey = `coach_r4_allornothing`; break;
                }

                // Governance: a sign-off template institutionalises rationality assurance.
                switch (d.governance) {
                    case `template`: ratDelta += 7; credDelta += 5; break;
                    case `review`: ratDelta += 1; break;
                    case `none`: ratDelta -= 5; coachKey = `coach_r4_nogov`; break;
                }

                // Conviction nudges quality.
                qualDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.signoff === `corrected` && d.phased === `milestones` && d.governance === `template`) ? `sum_r4_good` : (d.signoff === `original` ? `sum_r4_original` : `sum_r4_weak`);
            }

            // Resource accounting — clock and verification budget.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));
            ds.days = Math.max(0, Math.round((ds.days - daysSpent) * 10) / 10);

            // KPIs move on their deltas (clamped, but seeded low with headroom).
            ds.rationality = Math.max(0, Math.min(100, ds.rationality + ratDelta));
            ds.quality = Math.max(0, Math.min(100, ds.quality + qualDelta));
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credDelta));

            // Working NPV reflects the assumptions the controller has corrected so far.
            this._recomputeNpv(state);

            ds.rationalityHistory.push(Math.round(ds.rationality));
            ds.qualityHistory.push(Math.round(ds.quality));
            ds.credibilityHistory.push(Math.round(ds.credibility));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                rationality: Math.round(ds.rationality),
                rationalityDelta: Math.round(ratDelta),
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qualDelta),
                credibility: Math.round(ds.credibility),
                credibilityDelta: Math.round(credDelta),
                days: ds.days,
                budgetUsed: ds.budgetUsed,
                workingNpv: ds.workingNpv,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        // Working NPV: starts at the claimed +EUR 5.2M and migrates toward the
        // defensible figure as the controller corrects the optimistic assumptions.
        _recomputeNpv(state) {
            const d = state.decisions;
            const ds = state.domainState;
            let npv = this.CLAIMED_NPV;

            // Growth correction is the dominant driver (it alone flips +5.2 to the
            // concept's corrected -3.8 at realistic 1.5% volume).
            if (d.growth === `scenario`) npv += (this.CORRECTED_NPV - this.CLAIMED_NPV);   // full reframe to -3.8
            else if (d.growth === `flat3`) npv += (this.CORRECTED_NPV - this.CLAIMED_NPV) * 0.55;
            // keep6 -> no correction

            // Vendor savings haircut (-36% to 4.9M) is a smaller refinement on top.
            if (d.savings === `independent`) npv -= 0.9;
            else if (d.savings === `discount`) npv -= 0.5;

            // Sunk cost wrongly inflates the case if kept in.
            if (d.sunk === `keep`) npv += 1.1;
            else if (d.sunk === `partial`) npv += 0.5;

            // Ramp transition cost (~EUR 2.8M) if realistically modelled.
            if (d.ramp >= 9) npv -= 0.6;
            else if (d.ramp >= 5) npv -= 0.3;

            ds.workingNpv = Math.round(npv * 10) / 10;
        }

        setupUI(uiManager) {
            const self = this;
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`rationalityDisplay`, `domainState.rationality`, (v) => Math.round(Number(v)));
            uiManager.bind(`qualityDisplay`, `domainState.quality`, (v) => {
                const card = document.querySelector(`.ratcheck-card-quality`);
                if (card) {
                    card.classList.toggle(`ratcheck-q-good`, Number(v) >= 65);
                    card.classList.toggle(`ratcheck-q-bad`, Number(v) < 35);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => {
                const card = document.querySelector(`.ratcheck-card-credibility`);
                if (card) card.classList.toggle(`ratcheck-cred-low`, Number(v) < 30);
                return Math.round(Number(v));
            });
            uiManager.bind(`daysDisplay`, `domainState.days`, (v) => {
                const card = document.querySelector(`.ratcheck-card-clock`);
                if (card) card.classList.toggle(`ratcheck-clock-out`, Number(v) <= 0);
                return Number(v).toFixed(1);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => self._money(Math.round(Number(v)) * 1000, true) + ` / ` + self._money(self.BUDGET_CAP * 1000, true));
            uiManager.bind(`npvDisplay`, `domainState.workingNpv`, (v) => {
                const bar = document.querySelector(`.ratcheck-npv-bar`);
                if (bar) bar.classList.toggle(`ratcheck-npv-negative`, Number(v) < 0);
                return self._npvLabel(Number(v));
