            const toneReadout = document.getElementById(`toneReadout`);
            if (tone && toneReadout) {
                toneReadout.textContent = tone.value;
                tone.addEventListener(`input`, function() { toneReadout.textContent = tone.value; });
            }
        }

        // ---- locale-aware EUR formatters ----
        _isEs() {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            return lang === `es`;
        }
        // Compact money for the budget bar (EUR, thousands). amount is in raw EUR.
        _money(amountEur, compactK) {
            const es = this._isEs();
            if (compactK) {
                const k = Math.round(amountEur / 1000);
                return es ? (k + ` K€`) : (`€` + k + `K`);
            }
            return es ? (amountEur + ` €`) : (`€` + amountEur);
        }
        // NPV label in EUR millions, signed, locale-aware.
        _npvLabel(millions) {
            const es = this._isEs();
            const sign = millions >= 0 ? `+` : `−`;
            const abs = Math.abs(millions);
            if (es) {
                const num = abs.toFixed(1).replace(`.`, `,`);
                return sign + num + ` M€`;
            }
            return sign + `€` + abs.toFixed(1) + `M`;
        }

