        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.rationalityHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                ratcheckChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.rationalityHistory },
                        { data: ds.qualityHistory },
                        { data: ds.credibilityHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const rationality = Math.round(ds.rationality);
            const quality = Math.round(ds.quality);
            const credibility = Math.round(ds.credibility);
            return Math.max(0, Math.min(100, Math.round(rationality * 0.40 + quality * 0.35 + credibility * 0.25)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="ratcheck-cm-badge ratcheck-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="ratcheck-cm-badge ratcheck-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.signedOriginal) failBadge += ` <span class="ratcheck-cm-badge ratcheck-cm-no">` + T(`cm_signed`) + `</span>`;
            if (s.capitulated) failBadge += ` <span class="ratcheck-cm-badge ratcheck-cm-no">` + T(`cm_folded`) + `</span>`;
            if (s.detonated) failBadge += ` <span class="ratcheck-cm-badge ratcheck-cm-no">` + T(`cm_detonated`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="ratcheck-cm-metric"><span class="ratcheck-cm-mv">` + Math.round(s.rationality || 0) + `</span><span class="ratcheck-cm-ml">` + T(`cm_m_rationality`) + `</span></div>`
                + `<div class="ratcheck-cm-metric"><span class="ratcheck-cm-mv">` + Math.round(s.quality || 0) + `</span><span class="ratcheck-cm-ml">` + T(`cm_m_quality`) + `</span></div>`
                + `<div class="ratcheck-cm-metric"><span class="ratcheck-cm-mv">` + Math.round(s.credibility || 0) + `</span><span class="ratcheck-cm-ml">` + T(`cm_m_credibility`) + `</span></div>`
                + `<div class="ratcheck-cm-metric"><span class="ratcheck-cm-mv">` + (s.workingNpv != null ? s.workingNpv : `–`) + `</span><span class="ratcheck-cm-ml">` + T(`cm_m_npv`) + `</span></div>`;
            return ``
                + `<div class="ratcheck-completion">`
                +   `<div class="ratcheck-cm-head">`
                +     `<div class="ratcheck-cm-score">` + score + `<span class="ratcheck-cm-score-max">/100</span></div>`
                +     `<div class="ratcheck-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="ratcheck-cm-metrics">` + metrics + `</div>`
                +   `<div class="ratcheck-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="ratcheck-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const rationality = Math.round(ds.rationality);
            const quality = Math.round(ds.quality);
            const credibility = Math.round(ds.credibility);
            const composite = this._composite(ds);

            // Top-tier gate is deliberately strict: "Rationality Assured" must require a
            // near-perfect rationality score so that committing ANY of the five Common Errors
            // (compute-first, trust-vendor, keep-sunk, capitulate, sign-original) drops out of it.
            let performanceKey = `grade_rubber`;
            if (ds.signedOriginal) performanceKey = `grade_signed`;
            else if (ds.capitulated) performanceKey = `grade_folded`;
            else if (composite >= 80 && rationality >= 85 && quality >= 68) performanceKey = `grade_assured`;
            else if (composite >= 62) performanceKey = `grade_credible`;
            else if (composite >= 45) performanceKey = `grade_partial`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (composite >= 80 && rationality >= 85 && quality >= 68 && !ds.signedOriginal) insights.push(window.mySimulation.t(`insight_assured`));
            else if (ds.signedOriginal) insights.push(window.mySimulation.t(`insight_signed`));
            else if (ds.capitulated) insights.push(window.mySimulation.t(`insight_folded`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (rationality < 50) insights.push(window.mySimulation.t(`insight_lowrationality`));
            if (credibility < 35) insights.push(window.mySimulation.t(`insight_lowcred`));
            if (ds.detonated) insights.push(window.mySimulation.t(`insight_detonated`));
            if (ds.workingNpv < 0 && !ds.signedOriginal) insights.push(window.mySimulation.t(`insight_npvflipped`));

            return {
                rationality: rationality,
                quality: quality,
                credibility: credibility,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (!ds.signedOriginal && !ds.capitulated && composite >= 80 && rationality >= 85 && quality >= 68),
                signedOriginal: ds.signedOriginal,
                capitulated: ds.capitulated,
                detonated: ds.detonated,
                workingNpv: this._npvLabel(ds.workingNpv),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.signedOriginal) return window.mySimulation.t(`hint_signed`);
            if (ds.capitulated) return window.mySimulation.t(`hint_capitulated`);
            if (ds.detonated) return window.mySimulation.t(`hint_detonated`);
            if (state.currentPeriod >= 2 && ds.rationality < 40) return window.mySimulation.t(`hint_lowrationality`);
            if (ds.rationality >= 70 && ds.quality >= 65 && ds.credibility >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

